from collections import Counter

def min_coins_to_value(coin_values, target):
    count = Counter(coin_values)
    dp = [-1] * (target + 1)
    dp[0] = 0

    for i in range(1, target + 1):
        if dp[i] != -1:
            for coin, freq in count.items():
                if i + coin <= target:
                    if dp[i + coin] == -1 or dp[i + coin] > dp[i] + freq:
                        dp[i + coin] = dp[i] + freq
    return dp[target]

def main():
