def solve(n, q, coins, queries):
    # Convert list of coins into a set for O(1) average-time complexity lookups
    coin_set = set(coins)

    # Process each query
    results = []
    for b in queries:
        if b in coin_set:
            results.append(1)
        else:
            min_coins = float('inf')
            # Check all combinations of coins to find the minimum number of coins needed
            def backtrack(index, current_sum, count):
                nonlocal min_coins
                if current_sum == b:
                    min_coins = min(min_coins, count)
                    return
                if current_sum > b or index >= len(coins):
                    return
                backtrack(index + 1, current_sum + coins[index], count + 1)
                backtrack(index + 1, current_sum, count)

            backtrack(0, 0, 0)
            if min_coins == float('inf'):
                results.append(-1)
            else:
                results.append(min_coins)

    return results

